const AprilTagDefinitions::FamilyInfo *AprilTagDefinitions::GetFamilyInfo(const AprilTagFamily &family) {
    for (const auto &entry: families_) {
        if (entry.type == family) {
            return entry.info;
        }
    }
    return nullptr;
}

const AprilTagFamily AprilTagDefinitions::GetFamilyType(const std::string &family_name_str) {
    for (const auto &entry: families_) {
        if (family_name_str == entry.name || family_name_str == entry.official_name) {
            return entry.type;
        }
    }
    return AprilTagFamily::kUnknown;
}

